EXEC GENERIC.Pr_UpdateEventLog
 @EventTypeID,
 @InfoEventSeverityID,
 @ModuleID,
 'ACI-GBD-Medisys Synch Report: Medicare EFT Members Extract File Generation Started.'

DECLARE 
 @Threshold FLOAT = @0, 
 @TotalRows FLOAT = (
  SELECT COUNT(1) 
  FROM Invoice.Medicare_EFT_Subscribers
 ) 

SELECT CEILING(@TotalRows/@Threshold) AS Counter

EXEC GENERIC.Pr_UpdateEventLog
 @EventTypeID,
 @InfoEventSeverityID,
 @ModuleID,
 'ACI-GBD-Medisys Synch Report: Medicare EFT Members Extract File Generation Complete.'

